from itertools import permutations

names = ["Peter", "Eric", "Alice", "Arnold"]
smoothies = ["watermelon", "desert", "cherry", "dragonfruit"]
colors = ["green", "white", "red", "yellow"]
houses = [1, 2, 3, 4]

def house_of(value, mapping):
    return next(h for h in houses if mapping[h] == value)

solution = None

for name_perm in permutations(names):
    name_map = {h: name_perm[h - 1] for h in houses}
    for smoothie_perm in permutations(smoothies):
        smoothie_map = {h: smoothie_perm[h - 1] for h in houses}
        for color_perm in permutations(colors):
            color_map = {h: color_perm[h - 1] for h in houses}

            if name_map[house_of("dragonfruit", smoothie_map)] != "Eric":
                continue
            if smoothie_map[2] != "cherry":
                continue
            if smoothie_map[4] != "dragonfruit":
                continue
            if smoothie_map[house_of("Arnold", name_map)] != "watermelon":
                continue
            if color_map[1] != "white":
                continue
            if color_map[house_of("Peter", name_map)] != "white":
                continue
            if color_map[house_of("watermelon", smoothie_map)] != "yellow":
                continue
            if color_map[house_of("dragonfruit", smoothie_map)] != "red":
                continue

            solution = (name_map, smoothie_map, color_map)
            break
        if solution:
            break
    if solution:
        break

name_map, smoothie_map, color_map = solution

for h in houses:
    print(f"House {h}: {name_map[h]}, {smoothie_map[h]}, {color_map[h]}")

