from itertools import permutations

def solve():
    names = ["Alice", "Eric", "Bob", "Peter", "Arnold", "Carol"]
    heights = ["very tall", "tall", "super tall", "average", "very short", "short"]
    phones = ["oneplus 9", "google pixel 6", "samsung galaxy s21", "iphone 13", "huawei p50", "xiaomi mi 11"]

    for h_perm in permutations(heights):
        hp = {value: index + 1 for index, value in enumerate(h_perm)}
        if hp["super tall"] != 1 or hp["short"] != 6:
            continue

        for n_perm in permutations(names):
            np = {value: index + 1 for index, value in enumerate(n_perm)}

            if np["Carol"] != hp["very tall"]:
                continue
            if np["Arnold"] != hp["tall"]:
                continue
            if np["Bob"] + 1 != hp["tall"]:
                continue

            for p_perm in permutations(phones):
                pp = {value: index + 1 for index, value in enumerate(p_perm)}

                if np["Peter"] >= pp["iphone 13"]:
                    continue
                if hp["very short"] <= pp["google pixel 6"]:
                    continue
                if abs(pp["google pixel 6"] - hp["short"]) != 2:
                    continue
                if pp["samsung galaxy s21"] == 1:
                    continue
                if pp["oneplus 9"] + 1 != hp["short"]:
                    continue
                if pp["xiaomi mi 11"] != np["Carol"]:
                    continue
                if pp["google pixel 6"] <= np["Eric"]:
                    continue

                return n_perm, h_perm, p_perm

    return None


n_perm, h_perm, p_perm = solve()

for i in range(6):
