from collections import deque

def main():
    cat_values = {
        'name': ['Bob', 'Carol', 'Eric', 'Alice', 'Peter', 'Arnold'],
        'vacation': ['camping', 'cruise', 'mountain', 'cultural', 'city', 'beach'],
        'pet': ['fish', 'hamster', 'bird', 'rabbit', 'dog', 'cat'],
        'nationality': ['brit', 'swede', 'german', 'norwegian', 'dane', 'chinese'],
        'genre': ['biography', 'romance', 'mystery', 'fantasy', 'science fiction', 'historical fiction'],
        'car': ['tesla model 3', 'bmw 3 series', 'honda civic', 'chevrolet silverado', 'toyota camry', 'ford f150']
    }

    def N(v): return ('name', v)
    def Vac(v): return ('vacation', v)
    def P(v): return ('pet', v)
    def Nat(v): return ('nationality', v)
    def G(v): return ('genre', v)
    def C(v): return ('car', v)

    variables = [(cat, val) for cat, vals in cat_values.items() for val in vals]
    constraints = []

    def add(v1, v2, pred):
        constraints.append((v1, v2, pred))

    for cat, vals in cat_values.items():
        for i in range(len(vals)):
            for j in range(i + 1, len(vals)):
                v1 = (cat, vals[i])
                v2 = (cat, vals[j])
                add(v1, v2, lambda a, b: a != b)

    add(G('fantasy'), N('Peter'), lambda a, b: a == b)
    add(Nat('chinese'), Nat('dane'), lambda a, b: a > b)
    add(C('tesla model 3'), P('hamster'), lambda a, b: a == b)
    add(N('Carol'), Vac('beach'), lambda a, b: a == b)
    add(G('mystery'), Vac('city'), lambda a, b: abs(a - b) == 2)
    add(G('science fiction'), Vac('city'), lambda a, b: a + 1 == b)
    add(Nat('brit'), C('honda civic'), lambda a, b: a == b)
    add(G('fantasy'), C('toyota camry'), lambda a, b: abs(a - b) == 2)
    add(P('bird'), C('toyota camry'), lambda a, b: a == b)
    add(G('romance'), Vac('camping'), lambda a, b: a == b)
    add(N('Arnold'), Vac('cruise'), lambda a, b: a == b)
    add(Vac('camping'), P('rabbit'), lambda a, b: a + 1 == b)
    add(C('ford f150'), P('rabbit'), lambda a, b: a == b)
    add(G('fantasy'), N('Eric'), lambda a, b: a + 1 == b)
    add(Nat('german'), C('bmw 3 series'), lambda a, b: a == b)
    add(G('historical fiction'), Vac('camping'), lambda a, b: a < b)
    add(Nat('dane'), N('Bob'), lambda a, b: a == b)
    add(Nat('dane'), Nat('chinese'), lambda a, b: abs(a - b) == 2)
    add(Nat('swede'), Vac('cruise'), lambda a, b: a > b)

    domains = {v: set(range(1, 7)) for v in variables}

    domains[P('cat')] = {2}
    domains[C('honda civic')] = {1}
    domains[P('dog')] = {5}
    domains[Nat('dane')].discard(3)
    domains[N('Eric')].discard(6)
    domains[N('Eric')].discard(3)
    domains[Vac('cultural')].discard(1)
    domains[G('mystery')].discard(6)

    adj = {v: [] for v in variables}
    for v1, v2, pred in constraints:
        adj[v1].append((v2, pred))
        adj[v2].append((v1, lambda a, b, p=pred: p(b, a)))

    def ac3(dom):
        q = deque()
        for xi in variables:
            for xj, pred in adj[xi]:
                q.append((xi, xj, pred))

        while q:
            xi, xj, pred = q.popleft()
            new_domain = set()
            revised = False

            for a in dom[xi]:
                ok = False
                for b in dom[xj]:
                    if pred(a, b):
                        ok = True
                        break
                if ok:
                    new_domain.add(a)
                else:
                    revised = True

            if revised:
                if not new_domain:
                    return False
                dom[xi] = new_domain
                for xk, pred_xi_xk in adj[xi]:
                    q.append((xk, xi, lambda a, b, p=pred_xi_xk: p(b, a)))

        return True

    def search(dom):
        if any(not dom[v] for v in variables):
            return None

        candidates = [v for v in variables if len(dom[v]) > 1]
        if not candidates:
            return {v: next(iter(dom[v])) for v in variables}

        var = min(candidates, key=lambda v: (len(dom[v]), -len(adj[v])))

        for val in sorted(dom[var]):
            new_dom = {v: set(dom[v]) for v in variables}
            new_dom[var] = {val}
            if ac3(new_dom):
                sol = search(new_dom)
                if sol is not None:
                    return sol

        return None

    if not ac3(domains):
        return

    sol = search(domains)

    names = cat_values['name']
    vacations = cat_values['vacation']
    pets = cat_values['pet']
    nations = cat_values['nationality']
    genres = cat_values['genre']
    cars = cat_values['car']

    for h in range(1, 7):
        name = next(x for x in names if sol[N(x)] == h)
        vac = next(x for x in vacations if sol[Vac(x)] == h)
        pet = next(x for x in pets if sol[P(x)] == h)
        nat = next(x for x in nations if sol[Nat(x)] == h)
        genre = next(x for x in genres if sol[G(x)] == h)
        car = next(x for x in cars if sol[C(x)] == h)

        print(f"House {h}: {name}, {vac}, {pet}, {nat}, {genre}, {car}")


if __name__ == "__main__":
    main()

