            if pc["green"] != pa["horse"]:
                continue
            if pn["Arnold"] != pc["white"]:
                continue
            if pc["green"] + 1 != pc["white"]:
                continue
            if pn["Peter"] != pc["green"]:
                continue
            if pn["Eric"] != pa["bird"]:
                continue

            solution = (n, c, a)
            break
        if solution:
            break
    if solution:
        break

n, c, a = solution

