cat_data = [
    ("Name", ["Peter", "Bob", "Arnold", "Carol", "Eric", "Alice"]),
    ("Lunch", ["spaghetti", "stir fry", "stew", "soup", "grilled cheese", "pizza"]),
    ("Cigar", ["blends", "pall mall", "dunhill", "yellow monster", "prince", "blue master"]),
    ("Drink", ["boba tea", "water", "coffee", "root beer", "milk", "tea"]),
    ("Education", ["associate", "bachelor", "trade school", "doctorate", "high school", "master"]),
]

attrs = []
idx = {}
for cat, values in cat_data:
    for val in values:
        idx[(cat, val)] = len(attrs)
        attrs.append((cat, val))

N = len(attrs)


def I(cat, val):
    return idx[(cat, val)]


full = sum(1 << p for p in range(1, 7))
domains = [full] * N


def remove_bit(var, val):
    domains[var] &= ~(1 << val)


remove_bit(I("Name", "Bob"), 2)
remove_bit(I("Cigar", "prince"), 3)
remove_bit(I("Lunch", "soup"), 1)

constraints = []


def add(c1, v1, c2, v2, pred):
    constraints.append((I(c1, v1), I(c2, v2), pred))


add("Cigar", "blends", "Lunch", "pizza", lambda a, b: a < b)
add("Cigar", "pall mall", "Cigar", "dunhill", lambda a, b: a > b)
