cat_indices = {}
for cat, values in cat_data:
    cat_indices[cat] = [I(cat, v) for v in values]


def propagate(i, p, new_dom, new_ass):
    cat = attrs[i][0]
    for j in cat_indices[cat]:
        if j == i:
            continue
        if new_ass[j] == p:
            return False
        new_dom[j] &= ~(1 << p)
        if new_ass[j] == 0 and new_dom[j] == 0:
            return False

    for a, b, pred in constraints:
        if a == i:
            if new_ass[b] != 0:
                if not pred(p, new_ass[b]):
                    return False
            else:
                mask = new_dom[b]
                newmask = 0
                for q in range(1, 7):
                    if (mask & (1 << q)) and pred(p, q):
                        newmask |= (1 << q)
                if newmask == 0:
                    return False
                new_dom[b] = newmask
        elif b == i:
            if new_ass[a] != 0:
                if not pred(new_ass[a], p):
                    return False
            else:
                mask = new_dom[a]
                newmask = 0
                for q in range(1, 7):
                    if (mask & (1 << q)) and pred(q, p):
                        newmask |= (1 << q)
                if newmask == 0:
                    return False
                new_dom[a] = newmask

    return True


def search(cur_dom, assigned):
    best = -1
    best_count = 7

    for i in range(N):
        if assigned[i] == 0:
            c = bin(cur_dom[i]).count("1")
            if c < best_count:
                best_count = c
                best = i

    if best == -1:
        return assigned
    if best_count == 0:
        return None

    mask = cur_dom[best]
    for p in range(1, 7):
        if not (mask & (1 << p)):
            continue

        if any(assigned[j] == p for j in cat_indices[attrs[best][0]] if j != best):
            continue

        new_dom = cur_dom.copy()
        new_ass = assigned.copy()
        new_ass[best] = p
        new_dom[best] = 1 << p

        if propagate(best, p, new_dom, new_ass):
            result = search(new_dom, new_ass)
            if result is not None:
                return result

    return None


solution = search(domains, [0] * N)

for house in range(1, 7):
