def main():
    names = ["Carol", "Eric", "Peter", "Alice", "Bob", "Arnold"]
    lunches = ["spaghetti", "soup", "grilled_cheese", "stir_fry", "stew", "pizza"]
    colors = ["green", "purple", "blue", "red", "white", "yellow"]
    mothers = ["Holly", "Penny", "Aniya", "Kailyn", "Sarah", "Janelle"]
    styles = ["colonial", "craftsman", "modern", "ranch", "victorian", "mediterranean"]

    groups = [names, lunches, colors, mothers, styles]
    all_vars = names + lunches + colors + mothers + styles

    domains = {v: set(range(1, 7)) for v in all_vars}
    domains["Carol"] = {1, 2, 3, 4, 5}
    domains["spaghetti"] = {1, 2, 3, 4, 6}

    def eq(a, b):
        return a == b

    def left(a, b):
        return a + 1 == b

    def adjacent(a, b):
        return abs(a - b) == 1

    def less(a, b):
        return a < b

    def distance_three(a, b):
        return abs(a - b) == 3

    constraints = [
        ("Janelle", "colonial", eq),
        ("Peter", "green", eq),
        ("blue", "spaghetti", left),
        ("Penny", "red", left),
        ("blue", "Penny", eq),
        ("Aniya", "green", left),
        ("white", "Janelle", less),
        ("Eric", "grilled_cheese", eq),
        ("Holly", "Alice", left),
        ("Holly", "stew", adjacent),
        ("Alice", "ranch", eq),
        ("stir_fry", "purple", eq),
        ("red", "colonial", adjacent),
        ("soup", "Peter", eq),
        ("pizza", "Sarah", less),
        ("victorian", "grilled_cheese", eq),
        ("grilled_cheese", "Aniya", distance_three),
        ("Arnold", "red", eq),
        ("modern", "Arnold", eq),
        ("yellow", "mediterranean", eq),
    ]

    def propagate(dom):
        changed = True
        while changed:
            changed = False

            for group in groups:
                fixed_values = set()
                fixed = []
                for var in group:
                    if len(dom[var]) == 1:
                        value = next(iter(dom[var]))
                        if value in fixed_values:
                            return None
                        fixed_values.add(value)
                        fixed.append(value)

                for var in group:
                    if len(dom[var]) > 1:
                        for value in fixed:
                            if value in dom[var]:
                                dom[var].remove(value)
                                changed = True
                                if not dom[var]:
                                    return None

            for x, y, relation in constraints:
                new_x = set()
                for a in dom[x]:
                    if any(relation(a, b) for b in dom[y]):
                        new_x.add(a)
                if new_x != dom[x]:
                    if not new_x:
                        return None
                    dom[x] = new_x
                    changed = True

                new_y = set()
                for b in dom[y]:
                    if any(relation(a, b) for a in dom[x]):
                        new_y.add(b)
                if new_y != dom[y]:
                    if not new_y:
                        return None
                    dom[y] = new_y
                    changed = True

        return dom

    def search(dom):
        if all(len(dom[var]) == 1 for var in dom):
            return dom

        candidates = [var for var in dom if len(dom[var]) > 1]
        var = min(candidates, key=lambda v: len(dom[v]))

        for value in sorted(dom[var]):
            next_dom = {k: set(v) for k, v in dom.items()}
            next_dom[var] = {value}
            propagated = propagate(next_dom)
            if propagated is not None:
                result = search(propagated)
                if result is not None:
                    return result

        return None

    solution = search(domains)
    positions = {var: next(iter(solution[var])) for var in solution}

    houses = [{} for _ in range(7)]

    for var in names:
        houses[positions[var]]["Name"] = var
    for var in lunches:
        houses[positions[var]]["Lunch"] = var
    for var in colors:
        houses[positions[var]]["Color"] = var
    for var in mothers:
        houses[positions[var]]["Mother"] = var
    for var in styles:
        houses[positions[var]]["Style"] = var

    lunch_names = {
        "spaghetti": "spaghetti",
        "soup": "soup",
        "grilled_cheese": "grilled cheese",
        "stir_fry": "stir fry",
        "stew": "stew",
        "pizza": "pizza",
    }

    for i in range(1, 7):
        house = houses[i]
        print(
            f"House {i}: {house['Name']}, "
            f"{lunch_names[house['Lunch']]}, {house['Color']}, "
            f"{house['Mother']}, {house['Style']}"
        )


if __name__ == "__main__":
    main()

