import itertools

def to_dict(values, perm):
    return {values[i]: perm[i] for i in range(len(values))}

def main():
    positions = range(1, 6)
    names = ["Alice", "Peter", "Bob", "Eric", "Arnold"]
    flowers = ["tulips", "daffodils", "lilies", "roses", "carnations"]
    children = ["Fred", "Bella", "Timothy", "Meredith", "Samantha"]
    educations = ["high school", "bachelor", "doctorate", "master", "associate"]
    animals = ["cat", "fish", "dog", "horse", "bird"]

    name_candidates = []
    for perm in itertools.permutations(positions):
        d = to_dict(names, perm)
        if d["Arnold"] + 1 == d["Peter"]:
            name_candidates.append(d)

    animal_candidates = []
    for perm in itertools.permutations(positions):
        d = to_dict(animals, perm)
        if abs(d["cat"] - d["horse"]) == 2 and abs(d["dog"] - d["fish"]) == 2:
            animal_candidates.append(d)

    child_candidates = []
    for perm in itertools.permutations(positions):
        d = to_dict(children, perm)
        if d["Meredith"] != 3:
            child_candidates.append(d)

    flower_candidates = [to_dict(flowers, p) for p in itertools.permutations(positions)]
    education_candidates = [to_dict(educations, p) for p in itertools.permutations(positions)]

    for name in name_candidates:
        for flower in flower_candidates:
            if flower["tulips"] != name["Eric"]:
                continue
            for animal in animal_candidates:
                if name["Peter"] <= animal["dog"]:
                    continue
                if flower["roses"] != animal["bird"]:
                    continue
                if animal["bird"] + 1 != flower["daffodils"]:
                    continue
                for education in education_candidates:
                    if education["bachelor"] != name["Bob"]:
                        continue
                    if abs(flower["carnations"] - education["bachelor"]) != 2:
                        continue
                    if education["associate"] + 1 != flower["tulips"]:
                        continue
                    if abs(education["doctorate"] - animal["cat"]) != 2:
                        continue
                    for child in child_candidates:
                        if education["master"] != child["Bella"]:
                            continue
                        if name["Bob"] != child["Samantha"]:
                            continue
                        if flower["daffodils"] != child["Timothy"]:
                            continue
                        if child["Fred"] >= education["bachelor"]:
                            continue

                        rows = []
                        for house in range(1, 6):
                            name_at = next(k for k, v in name.items() if v == house)
                            flower_at = next(k for k, v in flower.items() if v == house)
                            child_at = next(k for k, v in child.items() if v == house)
                            edu_at = next(k for k, v in education.items() if v == house)
                            animal_at = next(k for k, v in animal.items() if v == house)
                            rows.append(
                                f"House {house}: {name_at}, {flower_at}, {child_at}, {edu_at}, {animal_at}"
                            )

                        print("\n".join(rows))
                        return

