    music = ("rock", "classical", "pop")

    name_perms = permutations(names)
    pet_perms = permutations(pets)
    book_perms = permutations(books)
    car_perms = permutations(cars)
    birthday_perms = permutations(birthdays)
    music_perms = permutations(music)

    for n, p, b, c, d, m in product(
        name_perms,
        pet_perms,
        book_perms,
        car_perms,
        birthday_perms,
        music_perms
    ):
        def pos(perm, value):
            return perm.index(value)

        if pos(b, "romance") + 1 != pos(c, "ford f150"):
            continue
        if pos(d, "sept") != pos(c, "toyota camry"):
            continue
        if pos(d, "sept") != pos(n, "Peter"):
