        if pos(p, "fish") == 1:
            continue
        if pos(n, "Arnold") != pos(p, "cat"):
            continue
        if pos(c, "tesla model 3") != pos(b, "science fiction"):
            continue
        if pos(b, "science fiction") == 2:
            continue
        if pos(c, "ford f150") != pos(m, "pop"):
            continue
        if pos(m, "rock") + 1 != pos(n, "Eric"):
            continue

        for i in range(3):
            print(f"House {i + 1}: {n[i]}, {p[i]}, {b[i]}, {c[i]}, {d[i]}, {m[i]}")
