    if "name" in pos and "hair" in pos:
        if pos["name"]["Eric"] != pos["hair"]["auburn"]:
            return False

    if "phone" in pos and "color" in pos:
        if not (pos["phone"]["xiaomi mi 11"] > pos["color"]["white"]):
            return False

    if "genre" in pos and "flower" in pos:
        if pos["genre"]["historical fiction"] != pos["flower"]["roses"]:
            return False
        if abs(pos["genre"]["historical fiction"] - pos["flower"]["tulips"]) != 1:
            return False

    if "flower" in pos and "color" in pos:
        if not (pos["flower"]["iris"] > pos["color"]["green"]):
