order = ["genre", "name", "hair", "flower", "color", "phone"]

def solve(i=0, pos=None):
    if pos is None:
        pos = {}

    if i == len(order):
        return {cat: dict(pos[cat]) for cat in order}

    cat = order[i]
    for candidate in all_perms[cat]:
        pos[cat] = candidate
        if valid(pos):
            result = solve(i + 1, pos)
            if result is not None:
                return result
        del pos[cat]

    return None

