def pos(cat, attr):
    d = solution.get(cat)
    if d is None:
        return None
    return d[attr]

def eq(c1, a1, c2, a2):
    v1 = pos(c1, a1)
    v2 = pos(c2, a2)
    if v1 is None or v2 is None:
        return True
    return v1 == v2

def plus1(c1, a1, c2, a2):
    v1 = pos(c1, a1)
    v2 = pos(c2, a2)
    if v1 is None or v2 is None:
        return True
    return v1 + 1 == v2

