from itertools import permutations

categories = {
    'name': ['Bob', 'Arnold', 'Alice', 'Eric', 'Peter'],
    'lunch': ['stew', 'spaghetti', 'grilled cheese', 'pizza', 'stir fry'],
    'color': ['green', 'blue', 'yellow', 'red', 'white'],
    'nationality': ['swede', 'brit', 'dane', 'german', 'norwegian'],
    'book': ['fantasy', 'biography', 'romance', 'mystery', 'science fiction'],
    'child': ['Timothy', 'Samantha', 'Meredith', 'Fred', 'Bella'],
}

order = ['name', 'color', 'nationality', 'lunch', 'child', 'book']
pos = {cat: {} for cat in categories}


def p(cat, val):
    return pos[cat].get(val)


def equal(cat1, val1, cat2, val2):
    a = p(cat1, val1)
    b = p(cat2, val2)
    return a is None or b is None or a == b


def valid_partial():
    if not equal('nationality', 'swede', 'child', 'Bella'):
        return False

    sf = p('book', 'science fiction')
    st = p('lunch', 'stew')
    if sf is not None and st is not None and abs(sf - st) != 2:
        return False

    if not equal('lunch', 'pizza', 'child', 'Fred'):
        return False

    w = p('color', 'white')
    if w is not None and w == 3:
        return False

    if not equal('color', 'yellow', 'name', 'Peter'):
        return False

    g = p('lunch', 'grilled cheese')
    m = p('child', 'Meredith')
    if g is not None and m is not None and g + 1 != m:
        return False

    if not equal('nationality', 'german', 'lunch', 'spaghetti'):
        return False

    if not equal('book', 'romance', 'lunch', 'stew'):
        return False

    sa = p('child', 'Samantha')
    ge = p('nationality', 'german')
    if sa is not None and ge is not None and sa + 1 != ge:
        return False

    if not equal('name', 'Alice', 'nationality', 'swede'):
        return False

    if not equal('name', 'Arnold', 'color', 'green'):
        return False

    arn = p('name', 'Arnold')
    if arn is not None and arn != 2:
        return False

    if not equal('child', 'Meredith', 'book', 'biography'):
        return False

    if not equal('nationality', 'norwegian', 'color', 'red'):
        return False

    ro = p('book', 'romance')
    if ro is not None and ro == 2:
        return False

    if not equal('lunch', 'spaghetti', 'name', 'Eric'):
        return False

    da = p('nationality', 'dane')
    ye = p('color', 'yellow')
    if da is not None and ye is not None and not (da < ye):
        return False

    my = p('book', 'mystery')
    red = p('color', 'red')
    if my is not None and red is not None and my + 1 != red:
        return False

    fr = p('child', 'Fred')
    if fr is not None and fr == 2:
        return False

    return True


def solve(i=0):
    if i == len(order):
        return valid_partial()

    cat = order[i]
    vals = categories[cat]

    for perm in permutations(vals):
        pos[cat] = {perm[j]: j for j in range(5)}
        if valid_partial() and solve(i + 1):
            return True

    pos[cat] = {}
    return False


solve()

display_cats = ['name', 'lunch', 'color', 'nationality', 'book', 'child']

for h in range(5):
    row = []
    for cat in display_cats:
        for value in categories[cat]:
            if pos[cat][value] == h:
                row.append(value)
                break
    print(f"House {h + 1}: {', '.join(row)}")

from itertools import permutations

def main():
    values = {
        'name': ['Peter', 'Arnold', 'Bob', 'Alice', 'Eric', 'Carol'],
        'mother': ['Holly', 'Aniya', 'Kailyn', 'Janelle', 'Penny', 'Sarah'],
        'lunch': ['stir fry', 'stew', 'spaghetti', 'soup', 'pizza', 'grilled cheese'],
        'animal': ['dog', 'horse', 'cat', 'fish', 'rabbit', 'bird'],
        'smoothie': ['watermelon', 'desert', 'lime', 'cherry', 'blueberry', 'dragonfruit'],
        'style': ['mediterranean', 'craftsman', 'victorian', 'colonial', 'modern', 'ranch']
    }

    perms = {
        cat: [{v: i for i, v in enumerate(p)} for p in permutations(vals)]
        for cat, vals in values.items()
    }

    order = ['animal', 'name', 'mother', 'smoothie', 'lunch', 'style']

    def ok(a):
        if 'mother' in a and 'style' in a:
            if a['mother']['Penny'] != a['style']['victorian']:
                return False
            if a['style']['modern'] != a['mother']['Kailyn']:
                return False
            if a['style']['ranch'] != a['mother']['Aniya']:
                return False

        if 'style' in a:
            if not (a['style']['modern'] > a['style']['victorian']):
                return False

        if 'smoothie' in a:
            if a['smoothie']['blueberry'] == 5:
                return False
            if a['smoothie']['cherry'] == 2:
                return False

        if 'mother' in a and 'smoothie' in a:
            if a['mother']['Sarah'] != a['smoothie']['blueberry']:
                return False

        if 'smoothie' in a and 'name' in a:
            if a['smoothie']['cherry'] != a['name']['Eric']:
                return False
            if abs(a['smoothie']['desert'] - a['name']['Peter']) != 3:
                return False

        if 'mother' in a:
            if a['mother']['Janelle'] == 2:
                return False

        if 'lunch' in a:
            if a['lunch']['spaghetti'] != 2:
                return False

        if 'animal' in a and 'mother' in a:
            if a['animal']['fish'] != a['mother']['Holly']:
                return False

        if 'animal' in a:
            if a['animal']['horse'] != 0:
                return False
            if a['animal']['bird'] != 2:
                return False

        if 'style' in a and 'lunch' in a:
            if a['style']['mediterranean'] != a['lunch']['stew']:
                return False

        if 'name' in a and 'animal' in a:
            if a['name']['Carol'] != a['animal']['horse']:
                return False
            if a['animal']['cat'] != a['name']['Bob']:
                return False
            if a['name']['Arnold'] != a['animal']['rabbit']:
                return False

        if 'style' in a and 'smoothie' in a:
            if a['style']['colonial'] != a['smoothie']['blueberry']:
                return False

        if 'lunch' in a and 'smoothie' in a:
            if a['lunch']['grilled cheese'] != a['smoothie']['dragonfruit']:
                return False
            if not (a['lunch']['pizza'] > a['smoothie']['dragonfruit']):
                return False
            if abs(a['smoothie']['watermelon'] - a['lunch']['pizza']) != 2:
                return False

        if 'mother' in a and 'name' in a:
            if not (a['mother']['Janelle'] < a['name']['Arnold']):
                return False
            if a['mother']['Aniya'] != a['name']['Carol'] + 1:
                return False
            if a['name']['Peter'] != a['mother']['Janelle']:
                return False

        if 'name' in a and 'style' in a:
            if not (a['name']['Arnold'] > a['style']['craftsman']):
                return False

        if 'animal' in a and 'lunch' in a:
            if abs(a['animal']['cat'] - a['lunch']['stir fry']) != 3:
                return False

        return True

    solution = None

    def dfs(i, a):
        nonlocal solution
        if i == len(order):
            solution = {k: dict(v) for k, v in a.items()}
            return True

        cat = order[i]
        for p in perms[cat]:
            a[cat] = p
            if ok(a):
                if dfs(i + 1, a):
                    return True
            del a[cat]

        return False

    dfs(0, {})

    rows = []
    for h in range(6):
        row = {}
        for cat in ['name', 'mother', 'lunch', 'animal', 'smoothie', 'style']:
            for val, pos in solution[cat].items():
                if pos == h:
                    row[cat] = val
                    break
        rows.append(row)

    for i, row in enumerate(rows, 1):
        print(f"House {i}: {row['name']}, {row['mother']}, {row['lunch']}, {row['animal']}, {row['smoothie']}, {row['style']}")

if __name__ == "__main__":
    main()

