def ok(a):
    if "lunch" in a and "flower" in a:
        if a["lunch"].index("stew") + 1 != a["flower"].index("tulips"):
            return False

    if "vacation" in a and "lunch" in a:
        if a["vacation"].index("camping") != a["lunch"].index("grilled cheese"):
            return False

    if "hair" in a and "name" in a:
        if not (a["hair"].index("black") < a["name"].index("Bob")):
            return False

    if "hobby" in a and "hair" in a:
        if a["hobby"].index("photography") != a["hair"].index("gray"):
            return False

    if "lunch" in a and "vacation" in a:
        if a["lunch"].index("pizza") != a["vacation"].index("cruise"):
            return False

    if "name" in a and "vacation" in a:
        if a["name"].index("Alice") != a["vacation"].index("city"):
