            return False

    if "vacation" in a and "hobby" in a:
        if abs(a["vacation"].index("cruise") - a["hobby"].index("knitting")) != 3:
            return False

    if "hair" in a and "lunch" in a:
        if a["hair"].index("red") != a["lunch"].index("spaghetti"):
            return False

    if "flower" in a:
        if a["flower"].index("carnations") == 1:
