            return False

    if "hobby" in a and "lunch" in a:
        if a["hobby"].index("photography") != a["lunch"].index("stew"):
            return False

    if "name" in a and "flower" in a:
        if a["name"].index("Eric") != a["flower"].index("daffodils"):
            return False

    return True


def fixed_perms(values, value, index):
    return [p for p in permutations(values) if p.index(value) == index]


