def backtrack(i, assign):
    if i == len(order):
        return dict(assign)

    category, values = order[i]
    for perm in values:
        assign[category] = perm
        if ok(assign):
            result = backtrack(i + 1, assign)
            if result is not None:
                return result
        del assign[category]

    return None


