from collections import deque

names = ["Eric", "Arnold", "Peter", "Bob", "Alice", "Carol"]
music = ["jazz", "country", "pop", "classical", "rock", "hip hop"]
styles = ["mediterranean", "modern", "colonial", "ranch", "victorian", "craftsman"]
sports = ["tennis", "baseball", "soccer", "volleyball", "swimming", "basketball"]
books = ["science fiction", "historical fiction", "mystery", "biography", "fantasy", "romance"]

groups = [names, music, styles, sports, books]
vars_order = [v for group in groups for v in group]

domain = {v: set(range(1, 7)) for v in vars_order}
domain["basketball"] = {4}

neighbors = {v: {} for v in vars_order}

def add_binary(a, b, pred):
    neighbors[a].setdefault(b, []).append(pred)
    neighbors[b].setdefault(a, []).append(lambda x, y, p=pred: p(y, x))

def eq(x, y):
    return x == y

add_binary("baseball", "Arnold", eq)
add_binary("Alice", "colonial", lambda x, y: x < y)
add_binary("country", "hip hop", lambda x, y: x + 1 == y)
add_binary("Peter", "victorian", eq)
add_binary("fantasy", "Peter", eq)
add_binary("baseball", "romance", eq)
add_binary("hip hop", "biography", lambda x, y: x < y)
add_binary("ranch", "romance", lambda x, y: x < y)
add_binary("Bob", "swimming", eq)
add_binary("romance", "mystery", lambda x, y: x < y)
add_binary("Peter", "basketball", lambda x, y: x < y)
add_binary("Bob", "jazz", eq)
add_binary("craftsman", "mystery", eq)
add_binary("volleyball", "mediterranean", lambda x, y: x > y)
