for group in groups:
    for i in range(len(group)):
        for j in range(i + 1, len(group)):
            add_binary(group[i], group[j], lambda x, y: x != y)

def ac3(dom):
    queue = deque()
    for x in vars_order:
        for y in neighbors[x]:
            queue.append((x, y))

    while queue:
        xi, xj = queue.popleft()
        revised = False

        for xval in list(dom[xi]):
            supported = False
            for yval in dom[xj]:
                ok = True
                for pred in neighbors[xi][xj]:
                    if not pred(xval, yval):
                        ok = False
                        break
                if ok:
                    supported = True
                    break
            if not supported:
                dom[xi].remove(xval)
                revised = True

        if revised:
            if not dom[xi]:
                return False
            for xk in neighbors[xi]:
                queue.append((xk, xi))

    return True

def solve(dom):
    unassigned = [v for v in vars_order if len(dom[v]) > 1]
    if not unassigned:
        return {v: next(iter(dom[v])) for v in vars_order}

    var = min(unassigned, key=lambda v: len(dom[v]))
    for val in sorted(dom[var]):
        newdom = {v: set(s) for v, s in dom.items()}
        newdom[var] = {val}
        if ac3(newdom):
            result = solve(newdom)
            if result is not None:
                return result
    return None

initial = {v: set(s) for v, s in domain.items()}
solution = solve(initial) if ac3(initial) else None

