def forward(assign, dom, idx, value):
    new_assign = assign[:]
    new_dom = [d.copy() for d in dom]
    new_assign[idx] = value
    new_dom[idx] = {value}

    for i, j, func in constraints:
        ai = new_assign[i]
        aj = new_assign[j]

        if ai != -1 and aj != -1:
            if not func(ai, aj):
                return None
        elif ai != -1:
            nd = set()
            for v in new_dom[j]:
                if func(ai, v):
                    nd.add(v)
            if not nd:
                return None
            new_dom[j] = nd
        elif aj != -1:
            nd = set()
            for v in new_dom[i]:
                if func(v, aj):
                    nd.add(v)
            if not nd:
                return None
            new_dom[i] = nd

    for k in range(n):
        if new_assign[k] == -1 and not new_dom[k]:
            return None

    return new_assign, new_dom


def search(assign, dom):
    if all(a != -1 for a in assign):
        return assign

    idx = min((i for i in range(n) if assign[i] == -1), key=lambda i: len(dom[i]))

    for value in sorted(dom[idx]):
        nxt = forward(assign, dom, idx, value)
        if nxt is not None:
            result = search(nxt[0], nxt[1])
            if result is not None:
                return result

    return None


