    (['modern', 'knitting'], lambda d: d['modern'] == d['knitting']),
    (['Peter'], lambda d: d['Peter'] != 3),
    (['photography', 'Peter'], lambda d: abs(d['photography'] - d['Peter']) == 1),
]

degree = {v: 0 for v in variables}
