    for var_list, predicate in constraints:
        domains = []
        for v in var_list:
            if v in assign:
                domains.append((assign[v],))
            else:
                domains.append(tuple(x for x in range(1, 7) if x not in used[category[v]]))
        possible = False
        for values in product(*domains):
            d = {v: value for v, value in zip(var_list, values)}
            if predicate(d):
                possible = True
                break
        if not possible:
            return False
    return True

