from itertools import permutations

def solve():
    names = ['Peter', 'Eric', 'Alice', 'Carol', 'Bob', 'Arnold']
    animals = ['horse', 'fish', 'cat', 'bird', 'dog', 'rabbit']
    months = ['sept', 'mar', 'jan', 'feb', 'april', 'may']
    mothers = ['Holly', 'Sarah', 'Penny', 'Kailyn', 'Aniya', 'Janelle']
    vacations = ['beach', 'cruise', 'cultural', 'camping', 'city', 'mountain']

    month_perms = [p for p in permutations(months) if p[1] == 'feb']
    animal_perms = [p for p in permutations(animals) if p[1] == 'fish']
    name_perms = [p for p in permutations(names) if p[1] == 'Carol']
    mother_perms = [p for p in permutations(mothers) if p[3] == 'Kailyn']
    vacation_perms = [p for p in permutations(vacations) if p[5] == 'cruise']

    for ms in month_perms:
        may_pos = ms.index('may')
        mar_pos = ms.index('mar')
        sept_pos = ms.index('sept')
        april_pos = ms.index('april')

        for ans in animal_perms:
            dog_pos = ans.index('dog')
            horse_pos = ans.index('horse')
            rabbit_pos = ans.index('rabbit')
            cat_pos = ans.index('cat')

            if dog_pos + 1 != horse_pos:
                continue
            if april_pos != dog_pos:
                continue
            if may_pos != rabbit_pos:
                continue
            if abs(mar_pos - rabbit_pos) != 3:
                continue

            for nms in name_perms:
                if nms[rabbit_pos] != 'Bob':
                    continue
                if nms[0] == 'Eric':
                    continue

                carol_pos = nms.index('Carol')
                peter_pos = nms.index('Peter')
                alice_pos = nms.index('Alice')

                for moms in mother_perms:
                    if moms[carol_pos] != 'Janelle':
                        continue
                    if moms[alice_pos] != 'Aniya':
                        continue
                    if abs(may_pos - moms.index('Sarah')) != 1:
                        continue
                    if not (may_pos > moms.index('Penny')):
                        continue
                    if moms.index('Holly') != cat_pos:
                        continue

                    for vs in vacation_perms:
                        if vs[peter_pos] != 'beach':
                            continue
                        if vs[cat_pos] != 'camping':
                            continue
                        if not (rabbit_pos > vs.index('cultural')):
                            continue
                        if vs[sept_pos] != 'city':
                            continue

                        for i in range(6):
                            print(f"House {i + 1}: {nms[i]}, {ans[i]}, {ms[i]}, {moms[i]}, {vs[i]}")
                        return

if __name__ == "__main__":
    solve()
